import * as THREE from 'three';
// A physical tabletop instrument inside the retained observation table footprint.
export function buildPendulumRig({root,box,sphere,beam,label}){const g=new THREE.Group();g.name='science.pendulum-rig';root.add(g);const x=-2.6,z=-2.4;box(2.20,.06,.92,'#e8dbc0',x,1.21,z,.04,g);for(const dx of[-.82,.82])box(.10,1.22,.12,'#698f84',x+dx,1.85,z-.08,.025,g);box(1.85,.12,.17,'#698f84',x,2.48,z-.08,.04,g);sphere(.075,'#bfab79',x,2.38,z-.01,1,1,1,g);beam([x,2.38,z-.01],[x+.25,1.49,z-.01],.018,'#576c65',g);const bob=sphere(.15,'#deb35e',x+.25,1.49,z-.01,1,1,1,g);bob.name='science.pendulum-bob';box(.30,.12,.30,'#477767',x,1.30,z+.18,.03,g);box(.06,.23,.08,'#477767',x-.17,1.39,z+.18,.018,g);box(.06,.23,.08,'#477767',x+.17,1.39,z+.18,.018,g);for(let i=0;i<7;i++)box(.07,.012,.16,'#a8a587',x-.3+i*.10,1.25,z+.32,.002,g);box(.46,.36,.12,'#748c7c',x+.74,1.47,z+.26,.04,g);box(.35,.21,.02,'#e0e6bb',x+.74,1.49,z+.33,.01,g);label('진자 실험',x,2.83,z+.12,1.65,'#35564b','#f2ead0',g);return g;}
